#nullable enable // autogenerated

using System;
using MVZ2.UI;
using UnityEngine;

namespace MVZ2.Customize
{
    public class CustomizeIndexButton : MonoBehaviour
    {
        public void SetText(string text)
        {
            textButton.Text.text = text;
        }
        private void Awake()
        {
            textButton.Button.onClick.AddListener(() => OnClick?.Invoke(this));
        }
        public event Action<CustomizeIndexButton>? OnClick;
        [SerializeField]
        private TextButton textButton = null!;

    }
}
